      const sportMap: Record<string, string> = { basketball: "basketball", football: "football", baseball: "baseball", hockey: "hockey" };
      const leagueMap: Record<string, string> = { nba: "nba", nfl: "nfl", mlb: "mlb", nhl: "nhl" };
