  const ARENA_LOCALHOST_IPS = new Set(["127.0.0.1", "::1", "::ffff:127.0.0.1", "localhost"]);

  async function getArenaAccess(deviceId: string, ipAddress?: string): Promise<{ freeUsed: number; sessionExpiry: number | null; freeTrialExpiry: number | null; lastTrialAt: number | null; hasPurchased: boolean }> {
    const db = new Pool({ connectionString: process.env.DATABASE_URL, max: 2 });
    try {
      // Ensure ip_address column exists on arena_access table
      await db.query(`ALTER TABLE arena_access ADD COLUMN IF NOT EXISTS ip_address TEXT`).catch(() => {});

      const result = await db.query(`SELECT free_used, session_expiry, free_trial_expiry, last_trial_at, has_purchased FROM arena_access WHERE device_id = $1`, [deviceId]);
      if (result.rows.length > 0) {
        const row = result.rows[0];
        return {
          freeUsed: parseInt(row.free_used) || 0,
          sessionExpiry: row.session_expiry ? parseInt(row.session_expiry) : null,
          freeTrialExpiry: row.free_trial_expiry ? parseInt(row.free_trial_expiry) : null,
          lastTrialAt: row.last_trial_at ? parseInt(row.last_trial_at) : null,
          hasPurchased: !!row.has_purchased,
        };
      }

      // New device — check if same IP already burned through free arena calls
      if (ipAddress && !ARENA_LOCALHOST_IPS.has(ipAddress)) {
        try {
          const ipCheck = await db.query(
            `SELECT free_used FROM arena_access WHERE ip_address = $1 AND device_id != $2 AND free_used >= $3 ORDER BY updated_at DESC LIMIT 1`,
            [ipAddress, deviceId, ARENA_FREE_LIMIT]
          );
          if (ipCheck.rows.length > 0) {
            // Same IP already exhausted free calls — pre-fill this new device as exhausted too
            await db.query(
              `INSERT INTO arena_access (device_id, free_used, ip_address, updated_at)
               VALUES ($1, $2, $3, NOW())
               ON CONFLICT (device_id) DO NOTHING`,
              [deviceId, ARENA_FREE_LIMIT, ipAddress]
            );
            return { freeUsed: ARENA_FREE_LIMIT, sessionExpiry: null, freeTrialExpiry: null, lastTrialAt: null, hasPurchased: false };
          }
        } catch {}
      }
    } catch (e: any) {
      console.error("getArenaAccess error:", e.message);
    } finally {
      await db.end();
    }
    return { freeUsed: 0, sessionExpiry: null, freeTrialExpiry: null, lastTrialAt: null, hasPurchased: false };
  }

  async function setArenaAccess(deviceId: string, access: { freeUsed: number; sessionExpiry: number | null; freeTrialExpiry: number | null; lastTrialAt?: number | null; hasPurchased?: boolean }, ipAddress?: string): Promise<void> {
    const db = new Pool({ connectionString: process.env.DATABASE_URL, max: 2 });
    try {
      await db.query(
        `INSERT INTO arena_access (device_id, free_used, session_expiry, free_trial_expiry, last_trial_at, has_purchased, ip_address, updated_at)
         VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())
         ON CONFLICT (device_id) DO UPDATE SET
           free_used = $2, session_expiry = $3, free_trial_expiry = $4,
           last_trial_at = COALESCE($5, arena_access.last_trial_at),
           has_purchased = arena_access.has_purchased OR $6,
           ip_address = COALESCE($7, arena_access.ip_address),
           updated_at = NOW()`,
        [deviceId, access.freeUsed, access.sessionExpiry, access.freeTrialExpiry, access.lastTrialAt ?? null, access.hasPurchased ?? false, ipAddress || null]
      );
    } catch (e: any) {
      console.error("setArenaAccess error:", e.message);
    } finally {
      await db.end();
    }
  }

  // ── POLITICAL FACTS IQ: all-time rolling average per persona (write-through cache) ──
  const iqAlltimeCache = new Map<string, number>();
  let iqCacheLoadedAt = 0;
  async function loadIqCache(): Promise<void> {
    const db = new Pool({ connectionString: process.env.DATABASE_URL, max: 2 });
    try {
      const rows = await db.query(`SELECT persona_id, avg_iq FROM persona_iq_alltime`);
      for (const row of rows.rows) {
        iqAlltimeCache.set(row.persona_id, parseFloat(row.avg_iq) || 100);
      }
      iqCacheLoadedAt = Date.now();
    } catch (e: any) {
      console.error("loadIqCache error:", e.message);
    } finally { await db.end(); }
  }
  loadIqCache().catch(() => {});
  const iqCacheTimer: any = setInterval(() => loadIqCache().catch(() => {}), 60_000);
  if (typeof iqCacheTimer?.unref === "function") iqCacheTimer.unref();
  function getPersonaAllTimeIq(personaId: string): number {
    return Math.round(iqAlltimeCache.get(personaId) ?? 100);
  }

  // ── LIE TALLY: per-persona daily + all-time global counter (write-through cache) ──
  function todayUtc(): string {
    return new Date().toISOString().slice(0, 10);
  }
  const lieTallyAllTimeCache = new Map<string, number>();
  const lieTallyTodayCache = new Map<string, number>();
  let lieTallyCacheLoadedAt = 0;
  // Refresh merges DB values with the in-memory cache via Math.max so that
  // optimistic increments from in-flight bumpLieTally calls (which write to the
  // cache before committing to DB) cannot be clobbered by a stale DB read.
  // Stale entries that no longer have any DB row simply keep their cached count
  // (they will be reconciled on the next bump's DB write).
  async function loadLieTalliesIntoCache(): Promise<void> {
    const db = new Pool({ connectionString: process.env.DATABASE_URL, max: 2 });
    try {
      const all = await db.query(`SELECT persona_id, SUM(count)::int AS total FROM lie_tallies GROUP BY persona_id`);
      const seenAll = new Set<string>();
      for (const row of all.rows) {
        const dbVal = parseInt(row.total) || 0;
        const cached = lieTallyAllTimeCache.get(row.persona_id) || 0;
        lieTallyAllTimeCache.set(row.persona_id, Math.max(dbVal, cached));
        seenAll.add(row.persona_id);
      }
      // Drop personas that have zero cached AND no DB row (avoids unbounded growth from typos)
      for (const k of Array.from(lieTallyAllTimeCache.keys())) {
        if (!seenAll.has(k) && (lieTallyAllTimeCache.get(k) || 0) === 0) lieTallyAllTimeCache.delete(k);
      }
      const today = await db.query(`SELECT persona_id, count FROM lie_tallies WHERE day = $1`, [todayUtc()]);
      const seenToday = new Set<string>();
      for (const row of today.rows) {
        const dbVal = parseInt(row.count) || 0;
        const cached = lieTallyTodayCache.get(row.persona_id) || 0;
        lieTallyTodayCache.set(row.persona_id, Math.max(dbVal, cached));
        seenToday.add(row.persona_id);
      }
      // Clear today cache entries from prior days that are no longer "today"
      for (const k of Array.from(lieTallyTodayCache.keys())) {
        if (!seenToday.has(k) && (lieTallyTodayCache.get(k) || 0) === 0) lieTallyTodayCache.delete(k);
      }
      lieTallyCacheLoadedAt = Date.now();
    } catch (e: any) {
      console.error("loadLieTalliesIntoCache error:", e.message);
    } finally {
      await db.end();
    }
  }
  loadLieTalliesIntoCache().catch(() => {});
  const lieTallyRefreshTimer: any = setInterval(() => { loadLieTalliesIntoCache().catch(() => {}); }, 60_000);
  if (typeof lieTallyRefreshTimer?.unref === "function") lieTallyRefreshTimer.unref();

  async function bumpLieTally(personaId: string): Promise<void> {
    if (!personaId) return;
    const day = todayUtc();
    lieTallyAllTimeCache.set(personaId, (lieTallyAllTimeCache.get(personaId) || 0) + 1);
    lieTallyTodayCache.set(personaId, (lieTallyTodayCache.get(personaId) || 0) + 1);
    const db = new Pool({ connectionString: process.env.DATABASE_URL, max: 2 });
    try {
      await db.query(
        `INSERT INTO lie_tallies (persona_id, day, count) VALUES ($1, $2, 1)
         ON CONFLICT (persona_id, day) DO UPDATE SET count = lie_tallies.count + 1`,
        [personaId, day]
      );
    } catch (e: any) {
      console.error("bumpLieTally error:", e.message);
    } finally {
      await db.end();
    }
  }
  function getGlobalLieCount(personaId: string): number {
    return lieTallyAllTimeCache.get(personaId) || 0;
  }
  function getTodayLieCount(personaId: string): number {
    return lieTallyTodayCache.get(personaId) || 0;
  }

  setTimeout(() => {
    fetchArenaTopics().catch((err) => console.error("Startup topic pre-warm failed:", err));
  }, 5000);

  app.get("/api/arena/topics", async (req, res) => {
    try {
      const category = (req.query.category as string) || "politics";
      const bust = req.query.bust === "1";

      if (category !== "politics") {
        // Bust: evict the cache and await a fresh generation so the response
        // contains new topics rather than falling back to defaults immediately.
        if (bust) {
          categoryTopicsCache.delete(category);
          categoryGenerationInProgress.delete(category);
          const fresh = await fetchCategoryTopics(category).catch(() => [] as any[]);
          const result = fresh.length > 0 ? fresh : getDefaultCategoryTopics(category);
          return res.json({ topics: result });
        }
        const cached = categoryTopicsCache.get(category);
        if (cached && cached.topics.length > 0 && Date.now() < cached.expires) {
          return res.json({ topics: cached.topics });
        }
        if (cached && cached.topics.length > 0) {
          if (!categoryGenerationInProgress.has(category)) fetchCategoryTopics(category).catch(() => {});
          return res.json({ topics: cached.topics });
        }
        if (categoryGenerationInProgress.has(category)) {
          return res.json({ topics: getDefaultCategoryTopics(category) });
        }
        fetchCategoryTopics(category).catch(() => {});
        return res.json({ topics: getDefaultCategoryTopics(category) });
      }

      // Politics / default path — bust awaits a fresh generation too.
      if (bust) {
        arenaTopicsCache = { topics: [], expires: 0 };
        topicGenerationInProgress = false;
        const fresh = await fetchArenaTopics().catch(() => [] as any[]);
        const result = fresh.length > 0 ? fresh : getDefaultArenaTopics();
        return res.json({ topics: result });
      }
      if (arenaTopicsCache.topics.length > 0 && Date.now() < arenaTopicsCache.expires) {
        return res.json({ topics: arenaTopicsCache.topics });
      }
      if (arenaTopicsCache.topics.length > 0) {
        if (!topicGenerationInProgress) {
          fetchArenaTopics().catch(() => {});
        }
        return res.json({ topics: arenaTopicsCache.topics });
      }
      if (topicGenerationInProgress) {
        return res.json({ topics: getDefaultArenaTopics() });
      }
      fetchArenaTopics().catch(() => {});
      res.json({ topics: getDefaultArenaTopics() });
    } catch (error: any) {
      console.error("Arena topics error:", error);
      res.json({ topics: getDefaultArenaTopics() });
    }
  });

  let breakingNewsCache: { headline: string; description: string; source: string; timestamp: number } | null = null;
  const BREAKING_NEWS_INTERVAL = 2 * 60 * 1000;
  let lastBreakingNewsTime = 0;

  app.get("/api/arena/breaking-news", async (_req, res) => {
    try {
      const now = Date.now();
      if (breakingNewsCache && now - breakingNewsCache.timestamp < BREAKING_NEWS_INTERVAL) {
        return res.json({ breakingNews: breakingNewsCache, isNew: false });
      }
      const feedPromises = NEWS_FEEDS.slice(0, 10).map(f => fetchRSSFeed(f.url, f.source));
      const results = await Promise.allSettled(feedPromises);
      const allHeadlines: { title: string; source: string }[] = [];
      for (const r of results) {
        if (r.status === "fulfilled") {
          allHeadlines.push(...r.value.map((h: any) => ({ title: h.title, source: h.source })));
        }
      }
      if (allHeadlines.length === 0) {
        return res.json({ breakingNews: null, isNew: false });
      }
      const randomIdx = Math.floor(Math.random() * Math.min(allHeadlines.length, 24));
      const picked = allHeadlines[randomIdx];
      const completion = await getClient().chat.completions.create({
        model: getFastModel(),
        messages: [
          { role: "system", content: "You are a breaking news writer. Given a headline, write a 1-2 sentence provocative description that would spark intense political debate. Make it dramatic and controversial. Return ONLY the description text, nothing else." },
          { role: "user", content: `Headline: ${picked.title} (${picked.source})` },
        ],
        max_completion_tokens: 100,
        temperature: 0.8,
      });
      const description = completion.choices[0]?.message?.content?.trim() || picked.title;
      breakingNewsCache = { headline: picked.title, description, source: picked.source, timestamp: now };
      lastBreakingNewsTime = now;
      res.json({ breakingNews: breakingNewsCache, isNew: true });
    } catch (error: any) {
      console.error("Breaking news error:", error);
      res.json({ breakingNews: null, isNew: false });
    }
  });

