  app.get("/api/arena/interview-history", async (req, res) => {
    try {
      const deviceId = req.headers["x-device-id"] as string;
      if (!deviceId) return res.status(400).json({ error: "Device ID required" });
      const db = new Pool({ connectionString: process.env.DATABASE_URL, max: 2 });
      try {
        const result = await db.query(
          `SELECT id, interviewer_id, interviewer_name, interviewee_id, interviewee_name,
                  duration_minutes, lie_count, message_count, started_at, ended_at, title, tags,
                  COALESCE((
                    SELECT COUNT(*)::int FROM jsonb_array_elements(lies) AS l
                    WHERE COALESCE((l->>'userFlagged')::boolean, false) IS TRUE
                  ), 0) AS user_lie_count
           FROM interview_history
           WHERE device_id = $1 AND deleted_at IS NULL
           ORDER BY ended_at DESC
           LIMIT 100`,
          [deviceId],
        );
        // Opportunistically purge soft-deleted interviews (and any bookmarks
        // that point at them) once they are past the 7-day restore window.
        // Intentionally kept alongside the daily background job in
        // server/index.ts: this gives the active user a same-second
        // experience (their list never shows expired rows even briefly),
        // while the background job is the safety net for inactive devices.
        // Skipped entirely when INTERVIEW_CLEANUP_DISABLED=1.
        if (!INTERVIEW_CLEANUP_DISABLED) try {
          const purgeBefore = Date.now() - INTERVIEW_RETENTION_MS;
          const purged = await db.query(
            `DELETE FROM interview_history
               WHERE device_id = $1 AND deleted_at IS NOT NULL AND deleted_at < $2
               RETURNING id`,
            [deviceId, purgeBefore],
          );
          const purgedIds = (purged.rows || []).map((r: any) => r.id).filter(Boolean);
          if (purgedIds.length > 0) {
            await db.query(
              `DELETE FROM interview_bookmarks WHERE device_id = $1 AND interview_id = ANY($2::text[])`,
              [deviceId, purgedIds],
            );
          }
        } catch {}
        const items = result.rows.map((r: any) => ({
          id: r.id,
          interviewerId: r.interviewer_id,
          interviewerName: r.interviewer_name,
          intervieweeId: r.interviewee_id,
          intervieweeName: r.interviewee_name,
          durationMinutes: r.duration_minutes,
          lieCount: r.lie_count,
          userLieCount: Number(r.user_lie_count) || 0,
          messageCount: r.message_count,
          startedAt: Number(r.started_at),
          endedAt: Number(r.ended_at),
          title: r.title || null,
          tags: Array.isArray(r.tags) ? r.tags : [],
        }));
        res.json({ items });
      } finally {
        await db.end();
      }
    } catch (error: any) {
      console.error("Interview history error:", error);
      res.status(500).json({ error: "Failed to load history" });
    }
  });

  // List soft-deleted interviews still inside the 7-day restore window.
