  app.post("/api/track-share", async (req, res) => {
    const db = new Pool({ connectionString: process.env.DATABASE_URL, max: 2 });
    try {
      const { deviceId, feature, contentPreview, platform } = req.body;
      if (!feature) {
        return res.status(400).json({ error: "Feature is required" });
      }
      await db.query(
        "INSERT INTO share_events (device_id, feature, content_preview, platform) VALUES ($1, $2, $3, $4)",
        [deviceId || null, feature, (contentPreview || "").slice(0, 200), platform || "unknown"]
      );
      const [totalResult, todayResult] = await Promise.all([
        db.query("SELECT COUNT(*) as total FROM share_events"),
        db.query("SELECT COUNT(*) as today FROM share_events WHERE created_at >= CURRENT_DATE"),
      ]);
      const totalShares = parseInt(totalResult.rows[0]?.total || "0");
      const sharesToday = parseInt(todayResult.rows[0]?.today || "0");
      res.json({ success: true, totalShares, sharesToday });
    } catch (error) {
      console.error("Track share error:", error);
      res.status(500).json({ error: "Failed to track share" });
    } finally {
      await db.end();
    }
  });

  app.get("/api/admin/shares", async (_req, res) => {
    const db = new Pool({ connectionString: process.env.DATABASE_URL, max: 2 });
    try {
      const [totalResult, byFeatureResult, recentResult, dailyResult] = await Promise.all([
        db.query("SELECT COUNT(*) as total FROM share_events"),
        db.query("SELECT feature, COUNT(*) as count FROM share_events GROUP BY feature ORDER BY count DESC"),
        db.query("SELECT feature, content_preview, platform, created_at FROM share_events ORDER BY created_at DESC LIMIT 20"),
        db.query("SELECT DATE(created_at) as day, COUNT(*) as count FROM share_events WHERE created_at > NOW() - INTERVAL '7 days' GROUP BY DATE(created_at) ORDER BY day DESC"),
      ]);

      res.json({
        totalShares: parseInt(totalResult.rows[0].total),
        byFeature: byFeatureResult.rows.map((r: any) => ({ feature: r.feature, count: parseInt(r.count) })),
        daily: dailyResult.rows.map((r: any) => ({ day: r.day, count: parseInt(r.count) })),
        recent: recentResult.rows.map((r: any) => ({
          feature: r.feature,
          preview: r.content_preview,
          platform: r.platform,
          createdAt: r.created_at,
        })),
      });
    } catch (error) {
      console.error("Admin shares error:", error);
      res.status(500).json({ error: "Failed to fetch share stats" });
    } finally {
      await db.end();
    }
  });

  function checkAdminKey(req: any): boolean {
    const adminKey = (req.headers["x-admin-key"] as string || "").trim();
    const expected = (process.env.ADMIN_PASSCODE || "").trim();
    if (!expected) {
      console.error("ADMIN_PASSCODE env var is not set!");
      return false;
    }
    return adminKey === expected;
  }

  app.get("/api/admin/auth-check", (req, res) => {
    const hasSecret = !!(process.env.ADMIN_PASSCODE || "").trim();
    const keyProvided = !!(req.headers["x-admin-key"] as string || "").trim();
    const valid = checkAdminKey(req);
    res.json({ secretConfigured: hasSecret, keyProvided, valid });
  });

  // Admin endpoint: preview how a persona sounds with a given emotion tag.
  // Usage:
  //   curl -X POST https://<host>/api/admin/tts-preview \
  //     -H "x-admin-key: <ADMIN_PASSCODE>" \
  //     -H "Content-Type: application/json" \
  //     -d '{"personaId":"miller","emotion":"angry","text":"This is a test."}' \
  //     --output preview.mp3
  //
  // personaId  — any key from PERSONA_VOICE_IDS (required)
  // emotion    — Fish Audio emotion tag, e.g. "angry","excited","sad","calm" (required)
  // text       — sample text to synthesise (required, max 500 chars)
  // speed      — optional playback speed multiplier (default: persona default or 1.0)
  app.post("/api/admin/tts-preview", async (req, res) => {
    if (!checkAdminKey(req)) {
      return res.status(403).json({ error: "Invalid admin key" });
    }
    try {
      const { personaId, emotion, text, speed } = req.body;
      if (!personaId || !emotion || !text) {
        return res.status(400).json({ error: "personaId, emotion, and text are required" });
      }

      const apiKey = process.env.FISH_AUDIO_API_KEY;
      if (!apiKey) {
        return res.status(500).json({ error: "FISH_AUDIO_API_KEY not configured" });
      }

      const voiceId = PERSONA_VOICE_IDS[personaId as string];
      if (!voiceId) {
        return res.status(400).json({
          error: `Unknown personaId '${personaId}'. Known personas: ${Object.keys(PERSONA_VOICE_IDS).join(", ")}`,
        });
      }

      const personaSpeed: number = typeof speed === "number" ? speed : (PERSONA_SPEED_MAP[personaId as string] ?? 1.0);
      const personaVolumeDb: number = PERSONA_VOLUME_BOOST[personaId as string] ?? 0;
      const safeText = applyPersonaTTSFormatting((text as string).slice(0, 500), personaId as string);

      console.log(`Admin TTS preview: persona=${personaId}, emotion=${emotion}, speed=${personaSpeed}`);
      const buffer = await fishAudioRequest(safeText, voiceId, personaSpeed, apiKey, 3, personaVolumeDb, emotion as string);

      res.setHeader("Content-Type", "audio/mpeg");
      res.setHeader("Content-Length", buffer.length.toString());
      res.setHeader("Content-Disposition", `attachment; filename="${personaId}-${emotion}.mp3"`);
      res.send(buffer);
    } catch (error: any) {
      console.error("Admin TTS preview error:", error);
      res.status(500).json({ error: "TTS generation failed", details: error.message });
    }
  });

